function withTimeout<T>(work: Promise<T>, ms: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error(`timed out after ${ms} ms`)), ms)
  })
  return Promise.race([work, timeout]).finally(() => clearTimeout(timer))
}

// Risky: if b rejects first, it is unhandled while we await a
const a = slowTask(), b = flakyTask()
const ra = await a
const rb = await b
// Safe: both handled from the start
const [x, y] = await Promise.all([slowTask(), flakyTask()])

async function retry<T>(op: () => Promise<T>, attempts: number, baseMs: number): Promise<T> {
  let lastError: unknown
  for (let n = 1; n <= attempts; n++) {
    try {
      return await op()
    } catch (error) {
      lastError = error
      if (n < attempts) await delay(baseMs * 2 ** (n - 1))
    }
  }
  throw lastError
}

