async function firstOk(urls: string[], fetchOne: (u: string) => Promise<string>): Promise<string> {
  try {
    return await Promise.any(urls.map(fetchOne))
  } catch (error) {
    if (error instanceof AggregateError) return `all ${error.errors.length} failed`
    throw error
  }
}

const fake = async (u: string) => {
  await delay(u.length)
  if (u.startsWith('bad')) throw new Error(u)
  return u
}

