solution:
function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

async function mapPool<T, R>(items: readonly T[], limit: number, worker: (item: T, index: number) => Promise<R>): Promise<R[]> {
  const results = new Array<R>(items.length)
  let next = 0
  async function lane(): Promise<void> {
    while (next < items.length) {
      const index = next++
      results[index] = await worker(items[index], index)
    }
  }
  const lanes = Math.min(Math.max(1, limit), items.length)
  await Promise.all(Array.from({ length: lanes }, lane))
  return results
}

async function runPool(delays: number[], limit: number): Promise<{ results: string[]; peak: number }> {
  let active = 0
  let peak = 0
  const results = await mapPool(delays, limit, async (ms, i) => {
    active++
    peak = Math.max(peak, active)
    await delay(ms)
    active--
    return `${i}:${ms}`
  })
  return { results, peak }
}

The pool starts `min(limit, n)` lanes. Each lane claims the next index with `next++`; that read-and-increment cannot interleave with another lane because JavaScript only switches between async functions at an `await`. Results are written by index, so `results` is in input order even though short jobs finish first. As soon as a lane's job finishes it loops and claims the next index, so the limit stays saturated instead of waiting for a whole batch. `peak` therefore reaches exactly `min(limit, n)`. Total time is roughly the makespan of greedy scheduling on `limit` machines, and memory is O(n) for the results. `mapPool` is generic, so the same helper types an array of user ids into `Promise<User[]>`.

