function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

async function retry<T>(
  op: (attempt: number) => Promise<T>,
  attempts: number,
  baseMs: number,
  onWait: (ms: number) => void = () => {},
): Promise<T> {
  const total = Math.max(1, attempts)
  let lastError: unknown
  for (let attempt = 1; attempt <= total; attempt++) {
    try {
      return await op(attempt)
    } catch (error) {
      lastError = error
      if (attempt < total) {
        const ms = baseMs * 2 ** (attempt - 1)
        onWait(ms)
        await delay(ms)
      }
    }
  }
  throw lastError
}

interface RetryReport {
  ok: boolean
  tries: number
  waits: number[]
  last: string
}

async function retryReport(failures: number, attempts: number, baseMs: number): Promise<RetryReport> {
  let tries = 0
  const waits: number[] = []
  const flaky = async (attempt: number): Promise<string> => {
    tries = attempt
    if (attempt <= failures) throw new Error(`fail #${attempt}`)
    return `ok on try ${attempt}`
  }
  try {
    const last = await retry(flaky, attempts, baseMs, ms => waits.push(ms))
    return { ok: true, tries, waits, last }
  } catch (error) {
    const last = error instanceof Error ? error.message : String(error)
    return { ok: false, tries, waits, last }
  }
}

